static MxWorld W;
static uint32_t digest(void){
  uint32_t h=2166136261u;
  for(int i=0;i<MX_ROWS*MX_COLS;i++)h=(h^W.grid[i])*16777619u;
  return h;
}
#define CHECK(c) do{if(!(c)){fprintf(stderr,"FAIL trial %d at line %d: %s\n",i,__LINE__,#c);return 1;}}while(0)
int main(void){
  init_tables();init_mats();
  for(int i=0;i<MX_TRIAL_COUNT;i++){
    const MxTrialLevel *t=&MX_TRIALS[i];
    memset(&W,0,sizeof W);build_trial(&W,i);
    CHECK(digest()==expected[i]);
    CHECK(W.ntargets==t->target_n&&W.nrooms==t->room_n&&W.npads==t->pad_n&&W.ntubes==t->tube_n&&W.walk==t->walk);
    /* New late-campaign lift mouths must clear the real native walker,
       and the existing transfer must deliver it to the elevated deck. */
    if(i>=540){
      CHECK(W.ntubes>0);
      MxTube *lift=&W.tubes[W.ntubes-1];
      CHECK(lift->by<lift->ay);
      W.man.mode=MAN_WALK;
      CHECK(walk_place(&W,lift->ax,lift->ay));
      CHECK(!wblocked(&W,lift->bx,lift->by));
      walk_tube_step(&W,R(1.0/60.0));
      CHECK(W.man.mode==MAN_WALK&&W.man.x==lift->bx&&W.man.y==lift->by&&W.man.tubeCd>0);
    }
    mx_load(&W,MX_TRIAL_START+i);
    int src=mx_stage_source(MX_TRIAL_START+i,0)-MX_TRIAL_START;
    const MxTrialLevel *first=&MX_TRIALS[src];
    CHECK(W.level==MX_TRIAL_START+i&&W.men==first->men&&W.ntargets==first->target_n);
    CHECK(digest()==expected[src]); /* no spawn collapse or misplaced supports */
    CHECK(strcmp(mx_level_name(W.level),t->name)==0&&strcmp(mx_level_tactic(W.level),t->tip)==0);
    CHECK(mx_targets_alive(&W)==first->target_n);
    mx_set_fight(&W,0);
    for(int frame=0;frame<30;frame++)mx_update(&W,R(1.0/60.0));
    CHECK(mx_targets_alive(&W)==first->target_n);
  }
  int i=0; MxStats S,T;mx_meta_init(&S);
  CHECK(mx_level_unlocked(&S,MX_TRIAL_START)&&mx_level_unlocked(&S,MX_NUM_LEVELS-1));
  CHECK(mx_trial_district_step(0,1)==MX_TRIAL_START);
  CHECK(mx_trial_district_step(MX_TRIAL_START,1)==MX_TRIAL_START+20);
  CHECK(mx_trial_district_step(MX_NUM_LEVELS-1,1)==0);
  CHECK(MX_JOURNAL_DISK_BYTES==3584&&MX_SAVE_MAX==3378);
  S.stars[59]=2;S.best[59]=12345;S.stars[659]=3;S.best[659]=67890;
  int stars=0;CHECK(mx_trial_cleared(&S,659,&stars)==1&&stars==3);CHECK(mx_trial_cleared(&S,59,&stars)==0&&stars==0);
  uint8_t disk[MX_JOURNAL_DISK_BYTES]={0};int n=mx_journal_pack(&S,0,NULL,7,disk,sizeof disk);
  CHECK(n==MX_JOURNAL_MAX&&mx_journal_record_size(disk,sizeof disk)==n);
  uint32_t gen=0;int outfit=0;mx_meta_init(&T);
  CHECK(mx_journal_unpack(&T,&outfit,NULL,&gen,disk,n)&&gen==7&&T.best[59]==12345&&T.best[659]==67890);
  /* Migrate the previous 220-stage MXS1 v2 save without changing old IDs. */
  uint8_t prior[1176]={0};
  memcpy(prior,"MXS1",4);prior[4]=2;prior[5]=220;prior[66+219]=3;
  mx_journal_put32(prior+66+220+5+4*219,765432);
  mx_journal_put32(prior+1172,mx_crc32(prior,1172));
  mx_meta_init(&T);CHECK(mx_meta_unpack(&T,&outfit,prior,sizeof prior));
  CHECK(T.stars[219]==3&&T.best[219]==765432&&T.stars[220]==0&&T.best[659]==0);
  uint8_t old3[1277]={0};memcpy(old3,"MXS1",4);old3[4]=3;old3[5]=240;old3[66+239]=3;
  mx_journal_put32(old3+66+240+5+4*239,93210);old3[1271]=16;old3[1272]=3|4|64;
  mx_journal_put32(old3+1273,mx_crc32(old3,1273));MxOptions opt;
  CHECK(mx_meta_unpack_opt(&T,&outfit,&opt,old3,sizeof old3)&&T.best[239]==93210&&T.best[659]==0&&opt.profile==3&&opt.eco&&opt.music_off&&opt.nofight);
  /* Real transition, not a synthetic UI state: clear all three actual
     layouts, including zero spare men at an intermediate stage. */
  for(int k=0;k<20;k++){
    i=MX_RELAY_START+k;mx_load(&W,i);mx_set_fight(&W,0);mx_set_collapse(&W,1);
    int score=12345;W.score=score;W.men=0;W.st_pw[0]=2;W.st_inflated=3;
    for(int d=0;d<3;d++){
      CHECK(W.level==i&&W.district==d&&W.state==MX_PLAY);
      CHECK(digest()==expected[mx_stage_source(i,d)-MX_TRIAL_START]);
      for(int n=0;n<W.ntargets;n++)W.targets[n].alive=0;
      W.winT=R(1.61);mx_update(&W,R(1.0/60.0));
      if(d<2){score+=3000;CHECK(W.state==MX_PLAY&&W.district==d+1&&W.score==score&&W.men==(d+1)*MX_RELAY_BONUS_MEN);
        CHECK(W.st_pw[0]==2&&W.st_inflated==3&&W.collapse&&W.nofight&&W.man.mode==MAN_AIM);}
      else CHECK(W.state==MX_WIN&&W.score==score+W.men*3000);
    }
  }
  printf("NATIVE_TRIAL_PACK_PASS levels=%d raw=%d command_bytes=%zu\n",MX_TRIAL_COUNT,MX_TRIAL_COUNT*MX_ROWS*MX_COLS,sizeof MX_TRIAL_DATA);
  return 0;
}
